{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Olsalazine, a poorly absorbed salicylate-based drug, had systemic availability of only 2.3% after a 1 g oral dose in fasting healthy volunteers, supporting low F for the similarly polar, poorly permeable salicylanilide query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Rebamipide, another aromatic amide-containing drug, has human oral bioavailability under 10%, supporting a low-F prediction for the query's amide-containing structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Phosphanilic acid, an aniline-derived polar molecule, had about 4% absolute oral bioavailability in humans, consistent with low absorption for the nitroaniline-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Tiludronic acid, a highly polar oral drug, showed absolute bioavailability of 6% (range 2–11%) in healthy volunteers, reinforcing that polar/ionizable molecules with poor permeability have low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Methyl parathion, a nitrophenyl-containing compound, had estimated F <1.7% in a patient, supporting low systemic availability for the nitrophenyl query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Ferulic acid, a phenolic acid, had only 3–10% bioavailability in humans, supporting low F for the phenolic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Salicylic acid, the acyl fragment of the query, showed essentially complete oral bioavailability in humans (F ~0.92), which is directionally contradictory; however, this reflects the small, highly soluble free acid rather than the intact poorly soluble salicylanilide.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a halogenated nitrophenyl salicylanilide (niclosamide-like). Multiple high-transfer human analogues with similar polar, poorly permeable features show low oral bioavailability (2–10%), and the only high-F analogue is the small salicylic acid fragment, which is not representative of the intact molecule. Therefore F is predicted to be below 20%.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule itself is present in the evidence set.",
    "The high-F salicylic acid data are for a fragment/metabolite and may not reflect the intact anilide.",
    "Some low-F records are for different chemical classes (bisphosphonates, organophosphates) and rely on indirect estimates."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

